import { mkdir, readFile, writeFile, rename, rm } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import { randomUUID } from 'node:crypto';
import { S3Client, PutObjectCommand, GetObjectCommand, DeleteObjectCommand } from '@aws-sdk/client-s3';

/** Keys are generated by the server; no user-supplied filesystem paths or public ACLs. */
export interface ObjectStore { put(key: string, bytes: Buffer): Promise<void>; get(key: string): Promise<Buffer>; delete(key: string): Promise<void> }
export class FileObjectStore implements ObjectStore {
  constructor(readonly root: string) {}
  private path(key: string) {
    if (!/^(temporary|permanent)\/[a-f0-9-]+\.png$/.test(key)) throw new Error('Invalid storage key');
    const path = resolve(this.root, key);
    if (!path.startsWith(resolve(this.root) + sep)) throw new Error('Invalid storage path');
    return path;
  }
  async put(key: string, bytes: Buffer) {
    const path = this.path(key); await mkdir(dirname(path), { recursive: true });
    const temp = path + '.' + randomUUID() + '.tmp';
    try { await writeFile(temp, bytes, { flag: 'wx', mode: 0o600 }); await rename(temp, path); }
    finally { await rm(temp, { force: true }); }
  }
  get(key: string) { return readFile(this.path(key)); }
  async delete(key: string) { await rm(this.path(key), { force: true }); }
}
export class S3ObjectStore implements ObjectStore {
  private client: S3Client;
  constructor(private bucket: string, region: string, endpoint?: string) {
    this.client = new S3Client({ region, endpoint, forcePathStyle: !!endpoint });
  }
  async put(key: string, bytes: Buffer) { await this.client.send(new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: bytes, ContentType: 'image/png' })); }
  async get(key: string) {
    const response = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
    if (!response.Body) throw new Error('Missing object');
    return Buffer.from(await response.Body.transformToByteArray());
  }
  async delete(key: string) { await this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key })); }
}
